function Car(brand) {
  this.brand = brand;
}

Car.prototype.wheels = 4;
Car.prototype.describe = function () {
  return this.brand + " on " + this.wheels;
};

const a = new Car("Fiat");
const b = new Car("Audi");
b.wheels = 3;

console.log(a.describe(), b.describe());
console.log(Object.hasOwn(a, "describe"), "describe" in a);
console.log(a.constructor === Car, Car.prototype.constructor === Car);
